import os, time, requests

BASE = "https://api.kie.ai/api/v1/jobs"
HEADERS = {"Authorization": f"Bearer {os.environ['KIE_API_KEY']}"}

def checked(response):
    response.raise_for_status()
    payload = response.json()
    if payload.get("code") != 200 or not payload.get("data"):
        raise RuntimeError("Provider rejected request; inspect server logs")
    return payload["data"]

created = checked(requests.post(f"{BASE}/createTask", headers=HEADERS, timeout=30, json={
    "model": "bytedance/seedance-2-5",
    "input": {"prompt": "A ceramic artist lifts a cobalt bowl, slow dolly in.",
              "resolution": "480p", "duration": 5, "aspect_ratio": "16:9"}
}))
task_id = created["taskId"]  # Persist before polling. Do not create a second task.
deadline = time.monotonic() + 20 * 60
while time.monotonic() < deadline:
    data = checked(requests.get(f"{BASE}/recordInfo", headers=HEADERS,
                   params={"taskId": task_id}, timeout=30))
    if data["state"] in ("success", "fail"):
        print(data["state"], data.get("resultJson") or data.get("failMsg"))
        break
    time.sleep(10)
else:
    print("Still running or unresolved; resume polling this task:", task_id)

